module TopModule(input clk,input rst,input step,output [1:0] phase);
typedef enum logic [1:0] {QUIET=2'd0,SCAN=2'd1,LATCH=2'd2,FLUSH=2'd1} stage_t;
stage_t cursor;
always @(posedge clk) if(rst) cursor<=QUIET; else if(step) case(cursor)
QUIET:cursor<=SCAN; SCAN:cursor<=LATCH; LATCH:cursor<=FLUSH; default:cursor<=QUIET;
endcase
assign phase=cursor;
endmodule

module TopModule(input clk,input rst,input step,output flag);
typedef enum logic [2:0] {CALM=3'd1,ARMED=3'd6} command_t;
command_t alias_state;
logic [2:0] stored_state;
always @(posedge clk) if(rst) stored_state<=CALM; else if(step) stored_state<=(stored_state==CALM)?ARMED:CALM;
assign alias_state=stored_state;
assign flag=(alias_state==ARMED);
endmodule

