assign flag=(alias_state==ARMED);
endmodule

module TopModule(input clk,input rst,input prefer,input serial,input alternate,output reg bit_out);
always @(posedge clk) if(rst) bit_out<=1'b0; else if(prefer) bit_out<=alternate; else bit_out<=bit_out^serial[4];
endmodule

module TopModule(input clk,input rst,input capture,input [4:0] packet,output parity);
always @(posedge clk) if(rst) parity<=1'b0; else if(capture) parity<=^packet;
endmodule

